add_action( 'init', 'qpedia_imp_register_cpt_tax', 5 );
function qpedia_imp_register_cpt_tax() {
    if ( ! taxonomy_exists( QPEDIA_IMP_TAX ) ) {
        register_taxonomy( QPEDIA_IMP_TAX, array( QPEDIA_IMP_CPT ), array(
            'hierarchical'      => true,
            'labels'            => array(
                'name'          => 'دسته‌های مقالات کوانتوم',
                'singular_name' => 'دسته مقاله کوانتوم',
            ),
            'show_ui'           => true,
            'show_admin_column' => true,
            'query_var'         => true,
            'rewrite'           => array( 'slug' => 'topic' ),
        ) );
    }

    if ( ! post_type_exists( QPEDIA_IMP_CPT ) ) {
        register_post_type( QPEDIA_IMP_CPT, array(
            'labels'             => array(
                'name'               => 'مقالات کوانتوم',
                'singular_name'      => 'مقاله کوانتوم',
                'add_new'            => 'افزودن مقاله جدید',
