                'not_found_in_trash' => 'مقاله‌ای در زباله‌دان یافت نشد',
                'menu_name'          => 'مقالات کوانتوم'
            ),
            'public'             => true,
            'publicly_queryable' => true,
            'show_ui'            => true,
            'show_in_menu'       => true,
            'query_var'          => true,
            'rewrite'            => array( 'slug' => 'article', 'with_front' => false ),
            'capability_type'    => 'post',
