/**
 * دریافت لیست مقالات آماده برای ایمپورت
 */
function qpedia_imp_get_articles() {
    return [
    {
        "slug": "quantum-fivefold-mental-map",
        "title": "جمع بندی پنج گانه: نقشه ذهنی برای نفهمیدن درست کوانتوم",
        "excerpt": "نقشه ذهنی پنج ایستگاهی برای نفهمیدن درست کوانتوم: رفتارها را به جای فرمول تماشا کنید، تمثیل را پل بدانید نه مقصد، مرز علم و قصه را مشخص کنید، سوال خوب بپرسید و روی شانه غول ها بایستید. هر ایستگاه با لینک به مقالات منتشرشده سایت همراه است.",
        "category": "fundamentals",
        "html": "<p>فرض کنید برای اولین بار نقشه متروی تهران را باز می کنید. در این نقشه فاصله واقعی ایستگاه ها را نمی بینید، عرض خیابان ها را نمی بینید و از شلوغی صبح هم خبری نیست؛ اما اگر مقصدتان را بدانید، همین نقشه ساده شما را دقیقا به همان جا می رساند. درک کوانتوم هم همین طور است: شما هرگز خود شهر را یک جا نمی بینید و اصلا قرار هم نیست ببینید؛ قرار است نقشه ای داشته باشید که بدانید کجا ایستاده اید، کجا می روید و کجا نباید پا بگذارید. ببینید بچه ها، می دونم کمی پیچیده به نظر میاد، علم کوانتوم همینه... اما جذابیتش هم همینه... در این مقاله یک نقشه ذهنی پنج ایستگاهی می سازیم تا به جای نفهمیدن اشتباه، به نفهمیدن درست کوانتوم برسید.</p>\n<h2>ایستگاه اول: فرمول ها را زمین بگذارید، رفتارها را تماشا کنید</h2>\n<p>مکانیک کوانتوم زبان ریاضی خودش را دارد، اما مسافر نقشه لازم نیست راننده مترو باشد. برای شروع کافی است چهار رفتار اصلی دنیای کوانتوم را بشناسید. اول، کوانتش: انرژی و خیلی از کمیت ها تکه تکه تحویل داده می شوند، نه پیوسته. دوم، برهم نهی: یک ذره پیش از اندازه گیری می تواند هم زمان در چند حالت باشد؛ <a href=\"https://qpedia.ir/quantum-superposition/\">مقاله برهم نهی کوانتومی</a> همین ماجرا را با مثال های ساده باز کرده است. سوم، عدم قطعیت: بعضی جفت ویژگی ها، مثل مکان و تکانه، هرگز هم زمان دقیق معلوم نمی شوند؛ اصل عدم قطعیت هایزنبرگ به زبان ساده را بخوانید. و چهارم، درهم تنیدگی: حالت دو ذره می تواند طوری به هم گره بخورد که دانستن یکی، دیگری را هم مشخص کند؛ جزئیاتش در مقاله درهم تنیدگی کوانتومی است. قرار نیست همین حالا همه اینها را عمیق بدانید؛ قرار است اسمشان را بدانید و جایشان را روی نقشه پیدا کنید.</p>\n<h2>ایستگاه دوم: تمثیل پل است، نه مقصد</h2>\n<p>سارا، دانش آموزی از مشهد، اولین بار اسم کوانتوم را در یک فیلم شنیده بود و فکر می کرد هر کسی کوانتوم را نفهمد حتما مشکلی در هوشش است. بعد از خواندن چند مقاله گفت: تازه فهمیدم <a href=\"https://qpedia.ir/schrodinger-cat/\">گربه شرودینگر</a> یک تمثیل فکری است، نه یک آزمایش واقعی. حق با ساراست: تمثیل ها، مثل نقشه مترو، قرار نیست خود شهر باشند؛ قرار است شما را تا ایستگاه بعدی ببرند. هر تمثیلی یک جایی می شکند، و این شکستن نه تقصیر شماست و نه عیب علم؛ ویژگی طبیعی ترجمه از زبان ریاضی به زبان روزمره است. <a href=\"https://qpedia.ir/quantum-analogy-exercise-boundary/\">تمرین ذهنی ساخت تمثیل و پیدا کردن مرز آن</a> دقیقا همین مهارت را به شما یاد می دهد. پس هر وقت تمثیلی دیدید، بپرسید: این پل تا کجا می برد و از کجا به بعد خراب می شود؟</p>\n<h2>ایستگاه سوم: مرز علم و قصه را همین اول مشخص کنید</h2>\n<p>یک مسافر خوب مرز بین خطوط رسمی نقشه و تبلیغات حاشیه آن را می شناسد. درباره کوانتوم هم همین طور است: چیزهایی هستند که در آزمایشگاه اندازه گرفته شده اند، و چیزهایی هستند که فقط قصه اند. رفتارهایی مثل تداخل در آزمایش دو شکاف و فروپاشی حالت در اندازه گیری، واقعیت های آزمایشگاهی هستند. اما بحث های بزرگ، مثل اینکه معنای اندازه گیری چیست، در زمین تفسیرهاست؛ جایی که فیزیک دان ها هنوز با هم اختلاف دارند و <a href=\"https://qpedia.ir/quantum-interpretation-debate/\">مقاله جنگ تفسیرها</a> را بخوانید. و یک قدم آن طرف تر، قصه هایی هستند که اصلا علم نیستند: اینکه «همه چیز انرژی است» پس انرژی درمانی معتبر است، یا اینکه کوانتوم به پزشکی جایگزین مشروعیت می دهد. مقاله «همه چیز انرژی است» یعنی چه؟ این قصه را باز کرده است. مرز را از اول مشخص کنید: آزمایش شده، تفسیر می شود، یا فروخته می شود؟</p>\n<h2>ایستگاه چهارم: سوال خوب، نصف مسیر است</h2>\n<p>علی از شیراز بعد از خواندن مقاله برهم نهی پرسید: اگر برهم نهی واقعی است، چرا میز و صندلی خانه ما هم زمان در دو جا نیستند؟ این دقیقا همان سوالی است که فیزیک دان ها را صد سال است سرگرم کرده است، و جوابش در <a href=\"https://qpedia.ir/why-large-objects-dont-superpose/\">مقاله چرا اشیای بزرگ برهم نهی نمی شوند</a> آمده است. نکته همین جاست: نفهمیدن درست یعنی سوال دقیق پرسیدن. به جای «کوانتوم عجیب است»، بپرسید کدام پدیده، در چه مقیاسی، با کدام آزمایش. سوال خوب، ایستگاه بعدی شما را خودش نشان می دهد.</p>\n<h2>ایستگاه پنجم: روی شانه های غول ها بایستید</h2>\n<blockquote><p>«اگر جلوتر دیده ام، به خاطر ایستادن روی شانه های غول ها بوده است.» — اسحاق نیوتن، نامه به رابرت هوک، ۱۶۷۵</p></blockquote>\n<p>هیچ کدام از ما قرار نیست کوانتوم را از صفر اختراع کنیم. ریچارد فاینمن، کسی که بهتر از هر کسی فیزیک را توضیح می داد، صادقانه گفت هیچ کس مکانیک کوانتومی را نمی فهمد. این جمله نقطه ضعف علم نیست؛ نقطه صداقت آن است. اینکه چرا اعتراف به نفهمیدن، خودش یک دستاورد است، در مقاله جداگانه <a href=\"https://qpedia.ir/quantum-understanding-achievement/\">نفهمیدن درست کوانتوم</a> باز شده است. اینجا فقط یادتان باشد: شما روی شانه غول ها ایستاده اید و نقشه را از کسانی می گیرید که صد سال است مسیر را پیموده اند.</p>\n<h2>جمع بندی</h2>\n<p>خوب یه جمع بندی کنیم: نفهمیدن درست کوانتوم یعنی پنج ایستگاه را بشناسید. رفتارها را به جای فرمول تماشا کنید؛ تمثیل را پل بدانید نه مقصد؛ مرز علم و قصه را مشخص کنید؛ سوال خوب بپرسید؛ و روی شانه غول ها بایستید. این نقشه، خود کوانتوم را برایتان حل نمی کند، چون قرار هم نیست حل کند؛ قرار است شما را در شهری ناآشنا راه ببرد، بدون اینکه گم شوید. و این، دقیقا همان بلوغ علمی است که فیزیک دان ها درباره اش حرف می زنند.</p>\n<h2>سوالات متداول</h2>\n<details><summary><strong>1. آیا باید ایستگاه ها را به همین ترتیب طی کنم؟</strong></summary><p>نه. ترتیب ایستگاه ها پیشنهادی است، نه قانون. می شود از ایستگاه چهارم (سوال خوب) شروع کرد یا مستقیم سراغ تمثیل ها رفت. فقط بدانید هر ایستگاه چه چیزی به نقشه شما اضافه می کند.</p></details>\n<details><summary><strong>2. اگر ریاضی بلد نباشم، این نقشه به دردم می خورد؟</strong></summary><p>بله. نقشه برای مسافر است، نه برای راننده مترو. برای فهمیدن ایده های اصلی هیچ فرمولی لازم نیست؛ ریاضی وقتی لازم می شود که بخواهید خودتان حساب کنید، و آن دیگر گردشگری نیست، کار است.</p></details>\n<details><summary><strong>3. این مقاله با «چرا نفهمیدن درست کوانتوم یک دستاورد است» چه فرقی دارد؟</strong></summary><p>آن مقاله توضیح می دهد چرا نفهمیدن طبیعی و حتی ارزشمند است؛ این مقاله می گوید چطور نفهمیدنی درست داشته باشید: یک نقشه پنج ایستگاهی عملی. هر دو مکمل هم اند.</p></details>\n<details><summary><strong>4. بعد از این نقشه چه مقاله ای بخوانم؟</strong></summary><p>پیشنهاد مسیر: اول برهم نهی کوانتومی، بعد اصل عدم قطعیت هایزنبرگ، بعد درهم تنیدگی کوانتومی، و در آخر گربه شرودینگر. بعد از آن، مقاله چرا اشیای بزرگ برهم نهی نمی شوند را بخوانید تا نقشه تان کامل شود.</p></details>\n<h2>منابع</h2>\n<ol><li><a href=\"https://www.britannica.com/biography/Isaac-Newton\">https://www.britannica.com/biography/Isaac-Newton</a></li><li><a href=\"https://www.nobelprize.org/prizes/physics/1965/feynman/biographical/\">https://www.nobelprize.org/prizes/physics/1965/feynman/biographical/</a></li><li><a href=\"https://www.feynmanlectures.caltech.edu/III_01.html\">https://www.feynmanlectures.caltech.edu/III_01.html</a></li></ol>"
    },
