/**
 * ساخت و تطبیق دسته‌بندی‌ها با والد درست
 */
function qpedia_imp_ensure_category( $slug ) {
    $tax = taxonomy_exists( QPEDIA_IMP_TAX ) ? QPEDIA_IMP_TAX : 'category';
    $term = get_term_by( 'slug', $slug, $tax );
    if ( $term && ! is_wp_error( $term ) ) {
        return (int) $term->term_id;
    }

    $cats = qpedia_imp_get_categories();
    $cat_info = null;
    foreach ( $cats as $c ) {
        if ( isset( $c['slug'] ) && $c['slug'] === $slug ) {
            $cat_info = $c;
            break;
        }
    }

    if ( ! $cat_info ) {
        $cat_info = array( 'slug' => $slug, 'name' => $slug, 'parent' => '' );
    }

    $parent_id = 0;
    if ( ! empty( $cat_info['parent'] ) ) {
        $parent_id = qpedia_imp_ensure_category( $cat_info['parent'] );
    }

    $res = wp_insert_term( $cat_info['name'], $tax, array(
        'slug'   => $slug,
        'parent' => $parent_id,
    ) );

    if ( is_wp_error( $res ) ) {
        $err_data = $res->get_error_data();
        if ( is_array( $err_data ) && ! empty( $err_data['term_id'] ) ) {
            return (int) $err_data['term_id'];
        }
        return 0;
    }

    return (int) $res['term_id'];
}

/**
 * تابع اصلی اجرای ایمپورت
 */
function qpedia_imp_run_import() {
    $articles = qpedia_imp_get_articles();
    $report = array(
        'created' => array(),
        'updated' => array(),
        'skipped' => array(),
        'errors'  => array(),
    );

    $post_type = post_type_exists( QPEDIA_IMP_CPT ) ? QPEDIA_IMP_CPT : 'post';
    $tax       = taxonomy_exists( QPEDIA_IMP_TAX ) ? QPEDIA_IMP_TAX : 'category';

    foreach ( $articles as $item ) {
        $slug    = sanitize_title( $item['slug'] );
        $title   = sanitize_text_field( $item['title'] );
        $excerpt = sanitize_textarea_field( $item['excerpt'] );
        $content = isset( $item['html'] ) ? $item['html'] : ( isset( $item['content'] ) ? $item['content'] : '' );
        $cat_slug= isset( $item['category'] ) ? $item['category'] : 'fundamentals';

        if ( empty( $slug ) ) {
            $report['errors'][] = 'اسلاگ نامعتبر برای مقاله: ' . $title;
            continue;
        }

        // بررسی وجود نوشته
        $existing = get_page_by_path( $slug, OBJECT, $post_type );
        if ( ! $existing ) {
            $query = new WP_Query( array(
                'name'           => $slug,
                'post_type'      => $post_type,
                'posts_per_page' => 1,
                'post_status'    => 'any',
                'no_found_rows'  => true,
            ) );
            if ( $query->have_posts() ) {
                $existing = $query->posts[0];
            }
        }

        // اگر مقاله قبلاً منتشر شده، به هیچ وجه تغییر نمی‌دهیم
        if ( $existing && 'publish' === $existing->post_status ) {
            $report['skipped'][] = array(
                'slug'  => $slug,
                'title' => $title,
                'id'    => $existing->ID,
                'msg'   => 'قبلاً منتشر شده است (دست‌نخورده باقی ماند)'
            );
            continue;
        }

        $postarr = array(
            'post_type'    => $post_type,
            'post_status'  => 'draft', // صریحاً به عنوان پیش‌نویس
            'post_title'   => $title,
            'post_name'    => $slug,
            'post_content' => $content,
            'post_excerpt' => $excerpt,
        );

        if ( $existing ) {
            $postarr['ID'] = $existing->ID;
            $post_id = wp_update_post( $postarr, true );
            $action = 'updated';
        } else {
            $post_id = wp_insert_post( $postarr, true );
            $action = 'created';
        }

        if ( is_wp_error( $post_id ) ) {
            $report['errors'][] = $title . ' (' . $slug . '): ' . $post_id->get_error_message();
            continue;
        }

        // انتساب دسته‌بندی
        $cat_id = qpedia_imp_ensure_category( $cat_slug );
        if ( $cat_id ) {
            wp_set_object_terms( (int) $post_id, array( $cat_id ), $tax, false );
        }

        // ذخیره متای سئو (برای سازگاری با رنک‌مث، یواست و قالب کیوپدیا)
        update_post_meta( $post_id, '_yoast_wpseo_metadesc', $excerpt );
        update_post_meta( $post_id, '_yoast_wpseo_title', $title );
        update_post_meta( $post_id, 'rank_math_description', $excerpt );
        update_post_meta( $post_id, 'rank_math_title', $title );
        update_post_meta( $post_id, '_qp_excerpt', $excerpt );

        $report[ $action ][] = array(
            'slug'  => $slug,
            'title' => $title,
            'id'    => $post_id,
        );
    }

    return $report;
}

