                $updated_count = isset( $report['updated'] ) ? count( $report['updated'] ) : 0;
                $skipped_count = isset( $report['skipped'] ) ? count( $report['skipped'] ) : 0;
                $errors_count  = isset( $report['errors'] ) ? count( $report['errors'] ) : 0;
            ?>
                <div class="qp-report-summary">
                    <div class="qp-stat-box" style="background: #e6fffa; color: #234e52; border: 1px solid #b2f5ea;">
                        <span class="qp-stat-num"><?php echo $created_count; ?></span>
                        <span class="qp-stat-label">پیش‌نویس جدید ایجاد شد</span>
                    </div>
                    <div class="qp-stat-box" style="background: #ebf8ff; color: #2a4365; border: 1px solid #bee3f8;">
                        <span class="qp-stat-num"><?php echo $updated_count; ?></span>
                        <span class="qp-stat-label">پیش‌نویس به‌روزرسانی شد</span>
                    </div>
                    <div class="qp-stat-box" style="background: #fffaf0; color: #744210; border: 1px solid #feebc8;">
                        <span class="qp-stat-num"><?php echo $skipped_count; ?></span>
                        <span class="qp-stat-label">رد شد (از قبل منتشرشده)</span>
                    </div>
                    <?php if ( $errors_count > 0 ) : ?>
                        <div class="qp-stat-box" style="background: #fff5f5; color: #742a2a; border: 1px solid #fed7d7;">
                            <span class="qp-stat-num"><?php echo $errors_count; ?></span>
                            <span class="qp-stat-label">خطا در ایمپورت</span>
                        </div>
                    <?php endif; ?>
                </div>
            <?php endif; ?>

            <form method="post" style="margin: 20px 0; display: flex; gap: 15px; align-items: center;">
                <?php wp_nonce_field( 'qpedia_imp_action', 'qpedia_imp_nonce' ); ?>
                <button type="submit" name="qpedia_imp_submit" class="qp-btn-primary">
                    <span class="dashicons dashicons-cloud-upload"></span>
                    شروع / اجرای مجدد واردسازی ۱۳ مقاله (به صورت پیش‌نویس)
                </button>
                <a href="<?php echo esc_url( $plugins_url ); ?>" class="qp-btn-secondary" style="color: #c53030; border-color: #feb2b2;">
                    <span class="dashicons dashicons-trash"></span>
                    مدیریت افزونه‌ها و حذف
                </a>
            </form>

            <h3 style="margin-top: 30px; font-size: 16px; color: #2d3748;">📋 فهرست ۱۳ مقالهٔ موجود در بسته ایمپورت:</h3>
            <table class="qp-table">
                <thead>
                    <tr>
                        <th style="width: 40px;">#</th>
                        <th>عنوان مقاله</th>
                        <th>اسلاگ (URL Slug)</th>
                        <th>دسته‌بندی</th>
                        <th>وضعیت در وردپرس</th>
                    </tr>
                </thead>
                <tbody>
                    <?php 
                    foreach ( $articles as $idx => $art ) : 
                        $slug = sanitize_title( $art['slug'] );
                        $existing = get_page_by_path( $slug, OBJECT, $post_type );
                        $status_html = '<span class="qp-status-pill qp-pill-new">آماده ایمپورت</span>';
                        
                        if ( $existing ) {
                            if ( 'publish' === $existing->post_status ) {
                                $status_html = '<span class="qp-status-pill qp-pill-skipped">منتشرشده (رد می‌شود)</span>';
                            } elseif ( 'draft' === $existing->post_status ) {
                                $status_html = '<span class="qp-status-pill qp-pill-created">پیش‌نویس موجود است</span>';
                            } else {
                                $status_html = '<span class="qp-status-pill qp-pill-updated">' . esc_html( $existing->post_status ) . '</span>';
                            }
                        }
                    ?>
                        <tr>
                            <td style="font-weight: bold; color: #718096;"><?php echo ( $idx + 1 ); ?></td>
                            <td style="font-weight: 600;">
                                <?php echo esc_html( $art['title'] ); ?>
                                <?php if ( $existing ) : ?>
                                    <div style="font-size: 11px; margin-top: 4px;">
                                        <a href="<?php echo esc_url( get_edit_post_link( $existing->ID ) ); ?>" target="_blank" style="color: #3182ce;">ویرایش در وردپرس &larr;</a>
                                    </div>
                                <?php endif; ?>
                            </td>
                            <td><code><?php echo esc_html( $slug ); ?></code></td>
                            <td><span style="background: #edf2f7; padding: 2px 8px; border-radius: 4px; font-size: 12px;"><?php echo esc_html( $art['category'] ); ?></span></td>
                            <td><?php echo $status_html; ?></td>
                        </tr>
                    <?php endforeach; ?>
                </tbody>
            </table>
        </div>
    </div>
    <?php
}
